from werkzeug.routing import Map, Rule
from werkzeug.routing.converters import FloatConverter, IntConverter

def test_bug():
    m = Map([
        Rule('/float/<float:val>', endpoint='float'),
        Rule('/int/<int(fixed_digits=4, signed=True):val>', endpoint='int')
    ])
    adapter = m.bind('example.com', '/')

    # Test float overflow becoming inf
    try:
        adapter.match('/float/1e99999')
    except Exception:
        pass
    else:
        # If it matched successfully as inf, that's the bug
        conv = FloatConverter(m)
        assert conv.to_python('1e99999') != float('inf')

    # Test int fixed_digits counting negative sign as digit
    try:
        adapter.match('/int/-123')
    except Exception:
        pass
    else:
        conv_int = IntConverter(m, fixed_digits=4, signed=True)
        assert conv_int.to_python('-123') is None
